body.script:
        let employees = JSON.parse(localStorage.getItem('omar_ios_emp')) || [
            { id: 1, name: 'أحمد محمد', role: 'مبيعات', rate: 15 },
            { id: 2, name: 'سالم علي', role: 'محاسب', rate: 20 }
        ];
        let logs = JSON.parse(localStorage.getItem('omar_ios_logs')) || [];
        let currentShiftType = 'الفترة الصباحية (10:00 - 4:00)';

        document.getElementById('shift-date').valueAsDate = new Date();

        function saveData() {
            localStorage.setItem('omar_ios_emp', JSON.stringify(employees));
            localStorage.setItem('omar_ios_logs', JSON.stringify(logs));
            renderAll();
        }

        function switchTab(tab) {
            ['shifts', 'employees', 'payroll'].forEach(t => {
                document.getElementById('tab-' + t).classList.add('hidden');
                document.getElementById('nav-' + t).className = 'flex flex-col items-center py-1 text-slate-400';
            });
            document.getElementById('tab-' + tab).classList.remove('hidden');
            document.getElementById('nav-' + tab).className = 'flex flex-col items-center py-1 text-emerald-400';
            renderAll();
        }

        function selectShift(type) {
            document.querySelectorAll('.shift-btn').forEach(b => {
                b.className = 'shift-btn text-right p-3 rounded-xl border border-white/10 bg-slate-900/60 flex justify-between items-center transition';
            });
            const activeClass = 'shift-btn text-right p-3 rounded-xl border border-emerald-500/50 bg-emerald-500/15 flex justify-between items-center transition';
            if (type === 'morning') {
                document.getElementById('btn-morning').className = activeClass;
                document.getElementById('shift-hours').value = 6;
                currentShiftType = 'الفترة الأولى (10:00 - 4:00)';
            } else if (type === 'evening') {
                document.getElementById('btn-evening').className = activeClass;
                document.getElementById('shift-hours').value = 6;
                currentShiftType = 'الفترة الثانية (4:00 - 10:00)';
            } else {
                document.getElementById('btn-double').className = activeClass;
                document.getElementById('shift-hours').value = 12;
                currentShiftType = 'فترتين كاملتين (10:00 - 10:00)';
            }
        }

        function addEmployee() {
            const name = document.getElementById('emp-name').value.trim();
            const role = document.getElementById('emp-role').value.trim() || 'موظف';
            const rate = parseFloat(document.getElementById('emp-rate').value);
            if (!name || isNaN(rate) || rate <= 0) return alert('يرجى إدخال اسم الموظف وسعر الساعة بشكل صحيح');
            employees.push({ id: Date.now(), name, role, rate });
            document.getElementById('emp-name').value = '';
            document.getElementById('emp-role').value = '';
            document.getElementById('emp-rate').value = '';
            saveData();
        }

        function deleteEmployee(id) {
            if (!confirm('هل أنت متأكد من حذف هذا الموظف وسجلاته؟')) return;
            employees = employees.filter(e => e.id !== id);
            logs = logs.filter(l => l.empId !== id);
            saveData();
        }

        function addShiftLog() {
            const empId = parseInt(document.getElementById('shift-emp').value);
            const date = document.getElementById('shift-date').value;
            const hours = parseFloat(document.getElementById('shift-hours').value);
            const bonus = parseFloat(document.getElementById('shift-bonus').value) || 0;
            const emp = employees.find(e => e.id === empId);
            if (!emp || isNaN(hours) || hours <= 0) return alert('يرجى اختيار الموظف وتحديد الساعات');

            const totalPay = (hours * emp.rate) + bonus;
            logs.unshift({
                id: Date.now(),
                empId: emp.id,
                empName: emp.name,
                date,
                shift: currentShiftType,
                hours,
                rate: emp.rate,
                bonus,
                totalPay
            });
            document.getElementById('shift-bonus').value = 0;
            saveData();
        }

        function deleteLog(id) {
            logs = logs.filter(l => l.id !== id);
            saveData();
        }

        function renderAll() {
            // Select Dropdown
            const select = document.getElementById('shift-emp');
            select.innerHTML = employees.map(e => `${e.name} (${e.rate} د.ل/ساعة)`).join('');

            // Stats
            const totalHours = logs.reduce((sum, l) => sum + l.hours, 0);
            const totalPay = logs.reduce((sum, l) => sum + l.totalPay, 0);
            document.getElementById('stat-employees').innerText = employees.length;
            document.getElementById('stat-hours').innerText = totalHours;
            document.getElementById('stat-total').innerText = totalPay.toFixed(1) + ' د.ل';

            // Logs
            const logsContainer = document.getElementById('logs-list');
            logsContainer.innerHTML = logs.length ? logs.map(l => `





${l.empName} (${l.totalPay} د.ل)

${l.date} | ${l.shift} (${l.hours} س)

                    حذف

            `).join('') : '
لا توجد سجلات دوام بعد';

            // Employees List
            const empContainer = document.getElementById('emp-list');
            empContainer.innerHTML = employees.map(e => `





${e.name}

${e.role} • سعر الساعة: ${e.rate} د.ل

                    حذف

            `).join('');

            // Payroll Report
            const reportContainer = document.getElementById('payroll-report');
            reportContainer.innerHTML = employees.map(e => {
                const empLogs = logs.filter(l => l.empId === e.id);
                const empHours = empLogs.reduce((s, l) => s + l.hours, 0);
                const empBonus = empLogs.reduce((s, l) => s + l.bonus, 0);
                const empTotal = empLogs.reduce((s, l) => s + l.totalPay, 0);
                return `







${e.name}

${e.role} (${e.rate} د.ل / ساعة)

                            ${empTotal.toFixed(1)} د.ل




عدد الفترات${empLogs.length}

إجمالي الساعات${empHours} ساعة

مكافآت/خصم${empBonus} د.ل


                `;
            }).join('');
        }

        renderAll();
